package com.nihongoacademy.ui.components
import androidx.compose.foundation.background
import androidx.compose.foundation.border
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.shape.CircleShape
import androidx.compose.material3.*
import androidx.compose.runtime.Composable
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.draw.clip
import androidx.compose.ui.graphics.StrokeCap
import com.nihongoacademy.ui.theme.*
@Composable fun PrimaryButton(text:String,onClick:()->Unit,modifier:Modifier=Modifier,enabled:Boolean=true){Button(onClick=onClick,enabled=enabled,modifier=modifier.heightIn(min=AcademyDimens.TouchTarget),shape=AcademyShapes.Medium,colors=ButtonDefaults.buttonColors(containerColor=AcademyColors.ButtonPrimary,contentColor=AcademyColors.ButtonPrimaryText,disabledContainerColor=AcademyColors.SurfaceElevated,disabledContentColor=AcademyColors.TextTertiary)){Text(text,style=MaterialTheme.typography.labelLarge)}}
@Composable fun SecondaryButton(text:String,onClick:()->Unit,modifier:Modifier=Modifier,enabled:Boolean=true){OutlinedButton(onClick=onClick,enabled=enabled,modifier=modifier.heightIn(min=AcademyDimens.TouchTarget),shape=AcademyShapes.Medium,colors=ButtonDefaults.outlinedButtonColors(contentColor=AcademyColors.TextPrimary)){Text(text,style=MaterialTheme.typography.labelLarge)}}
@Composable fun TextFieldLabeled(label:String,value:String,onValueChange:(String)->Unit,modifier:Modifier=Modifier,placeholder:String="",isError:Boolean=false){Column(modifier,verticalArrangement=Arrangement.spacedBy(AcademyDimens.Space2)){Text(label,style=MaterialTheme.typography.labelLarge,color=AcademyColors.TextSecondary);OutlinedTextField(value,onValueChange,modifier=Modifier.fillMaxWidth().heightIn(min=AcademyDimens.FieldHeight),placeholder={Text(placeholder,color=AcademyColors.TextTertiary)},isError=isError,singleLine=true,shape=AcademyShapes.Medium)}}
@Composable fun AcademyChip(text:String,selected:Boolean,modifier:Modifier=Modifier){Box(modifier.clip(AcademyShapes.Small).background(if(selected)AcademyColors.Sakura.copy(alpha=.14f) else AcademyColors.Surface).border(AcademyDimens.BorderWidth,if(selected)AcademyColors.Sakura else AcademyColors.Border,AcademyShapes.Small).padding(horizontal=AcademyDimens.Space3,vertical=AcademyDimens.Space2),contentAlignment=Alignment.Center){Text(text,color=if(selected)AcademyColors.Sakura else AcademyColors.TextSecondary,style=MaterialTheme.typography.labelLarge)}}
@Composable fun AcademyProgressBar(progress:Float,modifier:Modifier=Modifier){LinearProgressIndicator(progress={progress.coerceIn(0f,1f)},modifier=modifier.height(AcademyDimens.Space2).clip(CircleShape),color=AcademyColors.Sakura,trackColor=AcademyColors.SurfaceElevated,strokeCap=StrokeCap.Round)}
@Composable fun AcademyProgressRing(progress:Float,label:String,modifier:Modifier=Modifier){Box(modifier,contentAlignment=Alignment.Center){CircularProgressIndicator(progress={progress.coerceIn(0f,1f)},color=AcademyColors.Sakura,trackColor=AcademyColors.SurfaceElevated,strokeWidth=AcademyDimens.Space2);Text(label,style=MaterialTheme.typography.titleMedium,color=AcademyColors.TextPrimary)}}
@Composable fun AcademyCard(modifier:Modifier=Modifier,content:@Composable ColumnScope.()->Unit){Card(modifier=modifier,shape=AcademyShapes.Large,colors=CardDefaults.cardColors(containerColor=AcademyColors.Surface),elevation=CardDefaults.cardElevation(defaultElevation=AcademyDimens.CardElevation),content=content)}
@Composable fun EmptyState(title:String,description:String,action:String,onAction:()->Unit,modifier:Modifier=Modifier){Column(modifier.fillMaxWidth().padding(AcademyDimens.Space6),horizontalAlignment=Alignment.CenterHorizontally,verticalArrangement=Arrangement.spacedBy(AcademyDimens.Space3)){Text("桜",color=AcademyColors.Sakura,style=MaterialTheme.typography.displayLarge);Text(title,color=AcademyColors.TextPrimary,style=MaterialTheme.typography.titleLarge);Text(description,color=AcademyColors.TextSecondary,style=MaterialTheme.typography.bodyMedium);PrimaryButton(action,onAction)}}
@Composable fun AcademySkeleton(modifier:Modifier=Modifier,height:androidx.compose.ui.unit.Dp=AcademyDimens.Space8){Box(modifier.height(height).clip(AcademyShapes.Medium).background(AcademyColors.SurfaceElevated))}
@Composable fun ToastBanner(message:String,modifier:Modifier=Modifier,success:Boolean=true){Row(modifier.clip(AcademyShapes.Medium).background(AcademyColors.SurfaceElevated).border(AcademyDimens.BorderWidth,AcademyColors.Border,AcademyShapes.Medium).padding(AcademyDimens.Space4),verticalAlignment=Alignment.CenterVertically,horizontalArrangement=Arrangement.spacedBy(AcademyDimens.Space2)){Text(if(success)"✓" else "!",color=if(success)AcademyColors.Success else AcademyColors.Warning);Text(message,color=AcademyColors.TextPrimary,style=MaterialTheme.typography.bodyMedium)}}
}